SELECT
c.id as 'customer_id',
c.locale as 'locale',
c.salutation as 'salutation',
c.firstname as 'first_name',
c.lastname as 'last_name',
c.email as 'email',
c.phone as 'phone',
c.phone2 as 'phone2',
c.smsMarketing as 'sms_marketing',
c.emailMarketing as 'email_marketing',
c.createdbyCRM as 'created_by_crm',
UNIX_TIMESTAMP(c.createdAt) as 'customer_created_at',
c.createdByUser as 'customer_created_by_id',
c.createdByUserEmail as 'customer_created_by',
UNIX_TIMESTAMP(c.updatedAt) as 'customer_last_modified',
c.updatedByUser as 'customer_last_modified_by_id',
c.updatedByUserEmail as 'customer_last_modified_by',
UNIX_TIMESTAMP(c.deletedAt) as 'deleted_at', 
c.deletedByUser as 'deleted_by_id',
c.deletedByUserEmail as 'deleted_by',
c.country as 'country_id',
UNIX_TIMESTAMP(c.dataPrivacyConsent) as 'data_privacy_consent_at',
UNIX_TIMESTAMP(c.digitalCommunicationConsent) as 'digital_communication_consent_at',
c.city,
c.postcode,
c.address as 'customer_address'
FROM fcgContact.contact c
where c.updatedAt >= '{{params.start_ts}}' and c.updatedAt < '{{params.end_ts}}'